  "canonical_text": {
    "quote": "",
    "summary": "Editorial notes on episodes and figures associated with Atli, Guthrun, Sigurth, Gunnar, and Hogni. The notes discuss disputes over land and treasure, a maritime expedition, the restoration of outlaws, Atli's legal-council activity, ship burial, and a reference to Atli's mother appearing as an adder.",
    "language": "English",
    "quote_policy": "summarized"
  },
  "literal_observations": [
    {
      "id": "obs:1",
      "text": "Atli is described as reproaching Guthrun for inciting him to fight with his brothers in order to gain all of Buthli's land.",
      "category": "speech",
      "evidence_refs": [
        "ev:1"
      ]
    },
    {
      "id": "obs:2",
      "text": "Guthrun denies that she was responsible for Atli's quarrels with his brothers.",
      "category": "speech",
      "evidence_refs": [
        "ev:2"
      ]
    },
    {
      "id": "obs:3",
      "text": "The historical Attila is said to have killed his brother Bleda in order to rule alone.",
      "category": "action",
      "evidence_refs": [
        "ev:1"
      ]
    },
    {
      "id": "obs:4",
      "text": "Sigurth's hoard is described as treasure claimed by Atli through his relationship to Brynhild and Guthrun, while Gunnar and Hogni kept it; Atli charges Guthrun with connivance.",
      "category": "relationship",
      "evidence_refs": [
        "ev:1"
      ]
    },
    {
      "id": "obs:5",
      "text": "Atli's mother is said to appear as an adder that stings Gunnar to death in Oddrunargratr.",
      "category": "action",
      "evidence_refs": [
        "ev:1"
      ]
    },
    {
      "id": "obs:6",
      "text": "Guthrun, Gunnar, and Hogni are described as taking part in a maritime expedition from the land with Sigurth.",
      "category": "action",
      "evidence_refs": [
        "ev:3"
      ]
    },
    {
      "id": "obs:7",
      "text": "Men outlawed in a conquered land are described as being restored to their rights.",
      "category": "action",
      "evidence_refs": [
        "ev:4"
      ]
    },
    {
      "id": "obs:8",
      "text": "Sigurth is called a Hun-king in the note.",
      "category": "attribute",
      "evidence_refs": [
        "ev:5"
      ]
    },
    {
      "id": "obs:9",
      "text": "Atli is described as a Norse landowner who goes to the Thing, or general law council, to settle disputes.",
      "category": "action",
      "evidence_refs": [
        "ev:6"
      ]
    },
    {
      "id": "obs:10",
      "text": "The notes mention the burial of Norse chiefs in ships and say that this custom is applied to Atli.",
      "category": "action",
      "evidence_refs": [
        "ev:7"
      ]
    },
    {
      "id": "obs:11",
      "text": "The note states that all of Atli's heirs had been killed.",
      "category": "relationship",
      "evidence_refs": [
        "ev:8"
      ]
    },
    {
      "id": "obs:12",
      "text": "Two of Atli's brothers are said to have been killed, while two others died in battle with Gunnar and Hogni.",
      "category": "action",
      "evidence_refs": [
        "ev:2"
      ]
    }
