  "literal_observations": [
    {
      "id": "obs:1",
      "text": "Lohursp gives up authority, adopts the habit of a recluse, retires to a pilgrimage place near Balkh, and spends the remainder of his life in a solitary cell praying and worshipping God.",
      "category": "action",
      "evidence_refs": [
        "ev:1"
      ]
    },
    {
      "id": "obs:2",
      "text": "Gushtsp and his wife Kitabn have two sons, Isfendiyr and Bashtan, who are described as pious and devoted to the Almighty.",
      "category": "relationship",
      "evidence_refs": [
        "ev:2"
      ]
    },
    {
      "id": "obs:3",
      "text": "The minor rulers pay tribute to Gushtsp except Arjsp, whose forces are described as consisting of Dws, Peris, and men.",
      "category": "relationship",
      "evidence_refs": [
        "ev:2"
      ]
    },
    {
      "id": "obs:4",
      "text": "Zerdusht explains the doctrines of the fire-worshippers and rears a tree before Gushtsp's house.",
      "category": "action",
      "evidence_refs": [
        "ev:3"
      ]
    },
    {
      "id": "obs:5",
      "text": "Eating the tree's leaves is said to make a person learned in the mysteries of the future world, while eating its fruit is said to make a person perfect in wisdom and holiness.",
      "category": "attribute",
      "evidence_refs": [
        "ev:3"
      ]
    },
    {
      "id": "obs:6",
      "text": "Zerdusht restores the seriously ill Lohursp to health and receives increased favor from Gushtsp.",
      "category": "action",
      "evidence_refs": [
        "ev:4"
      ]
    },
    {
      "id": "obs:7",
      "text": "Zerdusht tells Gushtsp that he is God's prophet, has visited heaven and hell, knows the seven celestial mansions and sapphire thrones, and received heavenly secrets from an attendant angel.",
      "category": "speech",
      "evidence_refs": [
        "ev:4"
      ]
    },
    {
      "id": "obs:8",
      "text": "Zerdusht says that the Zendavesta descended from above for him and promises celestial felicity to Gushtsp if he follows it; Gushtsp becomes his convert and forsakes his former worship of God.",
      "category": "speech",
      "evidence_refs": [
        "ev:4",
        "ev:5"
      ]
    },
    {
      "id": "obs:9",
      "text": "Zerdusht says that he prepared a ladder by which he ascended into heaven and saw the Almighty.",
      "category": "action",
      "evidence_refs": [
        "ev:5"
      ]
    },
    {
      "id": "obs:10",
      "text": "Zerdusht questions Gushtsp's payment of tribute to Arjsp, and Gushtsp sends Arjsp a dispatch declaring that he will no longer pay tribute.",
      "category": "speech",
      "evidence_refs": [
        "ev:6"
      ]
    },
    {
      "id": "obs:11",
      "text": "Arjsp accuses Gushtsp of abandoning the true religion under Zerdusht's influence and threatens to invade his kingdom with fire and sword.",
      "category": "speech",
      "evidence_refs": [
        "ev:6"
      ]
    },
    {
      "id": "obs:12",
      "text": "Arjsp's letter is delivered by two demons; Gushtsp convenes a council, Zerdusht recommends war, Isfendiyr offers to lead the army, and Zarr is appointed commander because Isfendiyr is considered too young.",
      "category": "sequence",
      "evidence_refs": [
        "ev:6",
        "ev:7"
      ]
    },
    {
      "id": "obs:13",
      "text": "The threatened war begins, and Arjsp hastens into Iran.",
      "category": "sequence",
      "evidence_refs": [
        "ev:7"
      ]
    }
