  },
  "literal_observations": [
    {
      "id": "obs:1",
      "text": "Drb governs with humanity, justice, and benevolence, gives property to a washerman and his wife, and requires them to continue washing clothes at the river-side in case they find another infant-bearing box floating downstream.",
      "category": "action",
      "evidence_refs": [
        "ev:1"
      ]
    },
    {
      "id": "obs:2",
      "text": "An Arabian army of one hundred thousand men, commanded by Shb, invades the kingdom. Drb fights the army for three days and nights, and Shb is killed on the fourth morning.",
      "category": "action",
      "evidence_refs": [
        "ev:2"
      ]
    },
    {
      "id": "obs:3",
      "text": "Drb defeats Failaks of Rm and demands Failaks's daughter Nahd as the condition for peace. Failaks agrees, and Drb marries Nahd.",
      "category": "relationship",
      "evidence_refs": [
        "ev:3"
      ]
    },
